style.css:
@-moz-document domain("lichess.org") {
/* === Глобальные стили === */
  body {
    background-color: #0a0a0f !important;
    color: #e0f7ff !important;
    font-family: 'Orbitron', 'Rajdhani', 'Segoe UI', sans-serif !important;
    text-shadow: 0 0 5px rgba(0, 255, 255, 0.3);
    background-image: 
      radial-gradient(circle at 20% 30%, rgba(0, 255, 255, 0.05) 0%, transparent 30%),
      radial-gradient(circle at 80% 70%, rgba(255, 0, 128, 0.07) 0%, transparent 35%);
  }

  /* Замена шрифта на футуристический (если установлен локально или через Google Fonts) */
  @font-face {
    font-family: 'Orbitron';
    src: url(https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;700&display=swap);
  }

  h1, h2, h3, h4, h5, h6, .title, .menu-title {
    font-family: 'Orbitron', sans-serif !important;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #0ff !important;
    text-shadow: 0 0 10px #0ff, 0 0 20px #0ff;
  }

  /* === Темная матричная доска с неоновым эффектом === */
  .cg-board {
    border: 2px solid #0ff !important;
    box-shadow: 0 0 15px rgba(0, 255, 255, 0.5), inset 0 0 10px rgba(0, 255, 255, 0.2);
    border-radius: 4px;
  }

  /* Кастомизация клеток доски */
  .cg-square {
    background: transparent !important;
  }

  .cg-square-outer {
    background-color: #111 !important;
    border: 1px solid #1a1a2e !important;
  }

  /* Четные клетки — темно-фиолетовые */
  .cg-square-outer[data-color="w"] {
    background-color: #0d0d1a !important;
  }

  /* Нечетные — темно-синие с неоновым оттенком */
  .cg-square-outer[data-color="b"] {
    background-color: #0a0a2a !important;
  }

  /* Подсветка выбранных и возможных ходов */
  .cg-square-selected {
    background-color: rgba(255, 0, 128, 0.6) !important;
    box-shadow: 0 0 10px rgba(255, 0, 128, 0.8);
  }

  .cg-square-premove,
  .cg-square-dest {
    background-color: rgba(0, 255, 255, 0.3) !important;
    box-shadow: 0 0 8px rgba(0, 255, 255, 0.6);
  }

  /* Фигуры — оставляем стандартные, но добавим легкий светодиодный эффект */
  .cg-piece {
    filter: drop-shadow(0 0 4px rgba(0, 255, 255, 0.4));
  }

  /* === UI: Меню, заголовки, кнопки === */
  #site-header, #site-nav {
    background: linear-gradient(90deg, #0a0a0f, #1a0a2a) !important;
    border-bottom: 1px solid #0ff !important;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.2);
  }

  /* Кнопки с неоновым свечением */
  button, .button, .tab, .switcher a {
    background: #121225 !important;
    color: #0ff !important;
    border: 1px solid #0ff !important;
    box-shadow: 0 0 5px rgba(0, 255, 255, 0.3);
    text-transform: uppercase;
    font-family: 'Orbitron', sans-serif;
    transition: all 0.3s ease;
  }

  button:hover, .button:hover, .tab:hover {
    background: #1a1a3a !important;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.6), 0 0 15px rgba(255, 0, 128, 0.4);
    transform: translateY(-1px);
  }

  /* Активные вкладки */
  .switcher a.active {
    background: #220033 !important;
    border-bottom: none !important;
    box-shadow: inset 0 -2px 0 #f0f !important;
  }

  /* === Убираем или стилизуем рекламу === */
  .site-ad, .ad-container, .promotion-popup {
    display: none !important;
  }

  /* === Панель анализа и чата — стеклянный неон === */
  .game__meta, .mchat {
    background: rgba(10, 10, 30, 0.7) !important;
    backdrop-filter: blur(4px);
    border: 1px solid rgba(0, 255, 255, 0.2);
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.1);
  }

  /* Эффект "мигающего курсора" для активных элементов */
  input:focus, textarea:focus {
    outline: none !important;
    border-color: #0ff !important;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
  }

  /* === Эффект "ошибки" для предупреждений === */
  .error, .flash.error {
    background: #400 !important;
    color: #f00 !important;
    border: 1px solid #f00 !important;
    box-shadow: 0 0 10px rgba(255, 0, 0, 0.5);
  }

  /* === Скроллбар в стиле киберпанк === */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #0a0a0f;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(#00ffff, #ff0080);
    border-radius: 5px;
    border: 2px solid #0a0a0f;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(#00ffff, #f0f);
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
  }
}
